const responses = $json.responses || []
const fullText = responses.map(r => r.fullTextAnnotation?.text || '').join('

');

const cleanedText = fullText
  .replace(/
/g, '
')
  .replace(/[ 	]{2,}/g, ' ')
  .replace(/
\s*
/g, '

')
  .trim();

const chunkSize = 4000;
const chunks = [];
for (let i = 0; i < cleanedText.length; i += chunkSize) {
  chunks.push(cleanedText.slice(i, i + chunkSize));
}

return { json: { originalText: fullText, cleanedText, textChunks: chunks } };

let outputStr = $input.first().json.output;
let jsonMatch = outputStr.match(/({[\s\S]*})/);
if (!jsonMatch) throw new Error("No valid JSON found in the input!");
let jsonStr = jsonMatch[1];
let data = JSON.parse(jsonStr);
return [{ json: data }];
